// Auto-generated from public/downloads/foothills-google-maps-checklist.pdf
// Kept inline as base64 so Cloudflare Workers can serve it without node:fs.
export const CHECKLIST_PDF_BASE64 =
  "";

export function getChecklistPdfBuffer(): Uint8Array {
  const binary = atob(CHECKLIST_PDF_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}
